package com.codecrafters.kehdona.data.profile

import com.codecrafters.kehdona.model.Gender
import com.codecrafters.kehdona.model.MatchPreference

/**
 * A member's private profile. [name] is the name the person typed themselves; nothing
 * generated by an AI is ever written to it.
 */
data class UserProfile(
    val uid: String,
    val name: String,
    val email: String?,
    val phoneNumber: String?,
    val personalitySkipped: Boolean = false,
    /** As stated by the member; null until they choose. Never inferred. */
    val gender: Gender? = null,
    /** Only set when [gender] is [Gender.SelfDescribe]; private, never used for matching. */
    val genderSelfDescription: String? = null,
    val matchPreference: MatchPreference? = null,
) {
    /** Matching needs both a stated gender and a stated preference. */
    val hasMatchingDetails: Boolean get() = gender != null && matchPreference != null
}

/**
 * The finalized personality profile: ChatGPT's reply exactly as the person imported it.
 * It is created once and is read-only from then on (enforced by the Firestore rules).
 */
data class PersonalityProfile(
    val response: String,
    val importedAtMillis: Long?,
)

/** A profile read/write failure; [code] is the Firestore status, e.g. PERMISSION_DENIED. */
class ProfileException(
    message: String,
    val code: String? = null,
    cause: Throwable? = null,
) : Exception(message, cause)

/**
 * Stores profiles in Firestore at `users/{uid}` and the finalized personality profile at
 * `personalityProfiles/{uid}`. Every function throws [ProfileException].
 */
interface ProfileRepository {
    suspend fun getProfile(uid: String): UserProfile?

    /**
     * Creates the profile. If it already exists, only [UserProfile.name] is applied; the
     * original creation time and contact details are never overwritten.
     */
    suspend fun createProfile(profile: UserProfile)

    suspend fun getPersonality(uid: String): PersonalityProfile?

    /**
     * Saves and locks the personality profile in one step. If one is already finalized
     * (e.g. a retry after an earlier save actually succeeded), that stored profile is
     * returned unchanged; nothing is ever overwritten.
     */
    suspend fun finalizePersonality(uid: String, response: String): PersonalityProfile

    suspend fun skipPersonality(uid: String)

    /** Saves the member's own gender and match preference (from sign-up or "complete your profile"). */
    suspend fun updateMatchingDetails(
        uid: String,
        gender: Gender,
        genderSelfDescription: String?,
        matchPreference: MatchPreference,
    )
}
